interface AvailabilityResponse {
  searchId: string;
  offers: VehicleOffer[];
  serverNow: string;
}

type HoldResult =
  | { kind: 'held'; hold: VehicleHold; serverNow: string }
  | { kind: 'price-changed'; offer: VehicleOffer }
  | { kind: 'sold-out'; alternatives: VehicleOffer[] };

interface Reservation {
  reservationId: string;
  holdId: string;
  status: 'pending' | 'confirmed' | 'failed';
  pickupAt: LocalDateTime;
  returnAt: LocalDateTime;
  totalMinor: number;
  freeCancellationUntil: LocalDateTime;
}

interface RentalGateway {
  searchAvailability(input: { search: RentalSearch; signal: AbortSignal }): Promise<AvailabilityResponse>;
  createHold(input: { offerId: string; extras: string[]; idempotencyKey: string; signal: AbortSignal }): Promise<HoldResult>;
  extendHold(input: { holdId: string; signal: AbortSignal }): Promise<VehicleHold>;
  releaseHold(input: { holdId: string }): Promise<void>;
  confirmReservation(input: {
    holdId: string;
    driver: DriverDetails;
    paymentReference: string;
    idempotencyKey: string;
    signal: AbortSignal;
  }): Promise<Reservation>;
  getReservation(input: { reservationId: string; signal: AbortSignal }): Promise<Reservation>;
}
